param([ValidateSet('fixtures','execute')][string]$Action='execute',[string]$Dataset='',[switch]$TransformBoundary,[switch]$RevalidateNegative)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$base=Join-Path $root '.local/media-processing/supplemental';New-Item -ItemType Directory -Force $base|Out-Null
$image=(Get-Content -Raw (Join-Path $root '.local/media-processing/image.json')|ConvertFrom-Json).id
$limits=@('--init','--user','1000:1000','--read-only','--cap-drop','ALL','--security-opt','no-new-privileges:true','--pids-limit','64','--cpus','1','--memory','512m','--memory-swap','512m','--tmpfs','/scratch:size=128m,uid=1000,gid=1000,mode=0700','--tmpfs','/tmp:size=16m,uid=1000,gid=1000,mode=0700','--network','none')
function D([string[]]$Arguments){$result=& docker @Arguments;if($LASTEXITCODE -ne 0){throw 'Bounded supplemental Docker operation failed'};return $result}
function Save($path,$value){[IO.File]::WriteAllText($path,($value|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false))}
if($Action -eq 'fixtures'){$Dataset=Join-Path $base ([guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $Dataset|Out-Null;D (@('run','--rm')+$limits+@('--mount',"type=bind,source=$PSScriptRoot,target=/code,readonly",'--mount',"type=bind,source=$Dataset,target=/supplemental",'--entrypoint','node',$image,'/code/supplemental-fixtures.mjs'));Write-Output "DATASET=$Dataset";exit}
if(-not $Dataset){throw 'Explicit independent supplemental dataset required'};$Dataset=[IO.Path]::GetFullPath($Dataset);if(-not $Dataset.StartsWith([IO.Path]::GetFullPath($base)+[IO.Path]::DirectorySeparatorChar)){throw 'Outside supplemental workspace'}
$phase=if($RevalidateNegative){'classification-correction'}elseif($TransformBoundary){'boundary-transform'}else{'cases'};$attemptFile=if($RevalidateNegative){'classification-correction-attempts.json'}elseif($TransformBoundary){'boundary-attempts.json'}else{'attempts.json'};$manifest=Get-Content -Raw (Join-Path $Dataset 'manifest.json')|ConvertFrom-Json;$rows=@();$attempt=0
foreach($c in $manifest.cases){if($RevalidateNegative -and $c.id -notin @('TRUNCATED-MP4','TRUNCATED-HEIF','TRUNCATED-JPEG','CORRUPT-PNG')){continue};if($TransformBoundary -and $c.id -notin @('DURATION-299','DURATION-300','SIZE-PHOTO-BELOW','SIZE-PHOTO-EXACT','SIZE-VIDEO-BELOW','SIZE-VIDEO-EXACT')){continue};$attempt++;$dest=Join-Path $Dataset ($phase+'/'+$c.id);New-Item -ItemType Directory -Force $dest|Out-Null;$inputPath=Join-Path $Dataset ('inputs/'+$c.name);$name='el061-supp-'+[guid]::NewGuid().ToString('N');$id=$null;$start=[DateTime]::UtcNow
try{$spec=@{format=$c.format;outcome=if($c.expected -eq 'REJECTED'){'REJECT'}else{'ACCEPT'};mode=if($TransformBoundary){'transform'}else{$c.mode};metadata=$c.id.StartsWith('EXIF-')};$arg=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes(($spec|ConvertTo-Json -Compress)))
$id=(D (@('run','--detach','--name',$name,'--label','eventlens.spike=061-supplemental')+$limits+@('--mount',"type=bind,source=$PSScriptRoot,target=/code,readonly",'--mount',"type=bind,source=$inputPath,target=/input,readonly",'--entrypoint','node',$image,'/code/parser.mjs',$arg))).Trim()
do{& docker exec $id test -f /scratch/result.json 2>$null;if($LASTEXITCODE -eq 0){break};$state=D @('inspect','--format','{{json .State}}',$id)|ConvertFrom-Json;if(-not $state.Running){throw 'PROCESS_EXIT_WITHOUT_RESULT'};if(([DateTime]::UtcNow-$start).TotalSeconds -gt 120){throw 'ATTEMPT_TIMEOUT'};Start-Sleep -Milliseconds 300}while($true)
$bundle=(D @('exec',$id,'node','/code/export.mjs'))|ConvertFrom-Json;Save (Join-Path $dest 'result.json') $bundle.result
foreach($p in $bundle.files.PSObject.Properties){if($p.Name -notin @('thumbnail.jpg','preview.jpg','playback.mp4')){throw 'Unsafe output'};[IO.File]::WriteAllBytes((Join-Path $dest $p.Name),[Convert]::FromBase64String($p.Value))}
$runtime=D @('inspect','--format','{{json .HostConfig}}',$id)|ConvertFrom-Json;$cgroup=D @('exec',$id,'sh','-c','cat /sys/fs/cgroup/memory.peak; cat /sys/fs/cgroup/memory.events')
$rows+=@{caseId=$c.id;expected=$c.expected;mode=$spec.mode;result=$bundle.result;elapsedMs=([DateTime]::UtcNow-$start).TotalMilliseconds;runtime=@{image=$image;memory=$runtime.Memory;nanoCpus=$runtime.NanoCpus;pids=$runtime.PidsLimit;network=$runtime.NetworkMode;readonly=$runtime.ReadonlyRootfs;capDrop=$runtime.CapDrop;securityOpt=$runtime.SecurityOpt;user='1000:1000';scratchBytes=134217728;tmpBytes=16777216};cgroup=$cgroup;assertion=if($bundle.result.outcome -eq $c.expected -and $bundle.result.originalUnchanged -and $bundle.result.originalSha256 -eq $c.originalSha256){'PASS'}else{'FAIL'}}
}catch{$rows+=@{caseId=$c.id;assertion='FAIL';error='Bounded attempt failed; retained for diagnosis';exceptionClass=$_.Exception.Message}}finally{if($id){D @('rm','--force',$id)|Out-Null}}
Save (Join-Path $Dataset $attemptFile) $rows;Write-Output "SUPPLEMENT $attempt/$($manifest.cases.Count) $($c.id) $($rows[-1].assertion)"
}
Save (Join-Path $Dataset ($phase+'-summary.json')) @{dataset=(Split-Path $Dataset -Leaf);caseCount=$rows.Count;passed=@($rows|Where-Object assertion -eq 'PASS').Count;failed=@($rows|Where-Object assertion -eq 'FAIL').Count;experimentOnly=$true;canonicalCorpusTouched=$false;physicalEvidenceTouched=$false;result='PENDING_FINAL_REVIEW'}
